import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"ADR-002 Terraform provisions dependencies, Wrangler owns Workers","description":"","frontmatter":{},"headers":[],"relativePath":"adr/002-terraform-wrangler-boundary.md","filePath":"adr/002-terraform-wrangler-boundary.md","lastUpdated":1786319962000}`),a={name:`adr/002-terraform-wrangler-boundary.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /adr/002-terraform-wrangler-boundary.md for this page in Markdown format</div><h1 id="adr-002-terraform-provisions-dependencies-wrangler-owns-workers" tabindex="-1">ADR-002 Terraform provisions dependencies, Wrangler owns Workers <a class="header-anchor" href="#adr-002-terraform-provisions-dependencies-wrangler-owns-workers" aria-label="Permalink to “ADR-002 Terraform provisions dependencies, Wrangler owns Workers”">​</a></h1><p><strong>Status:</strong> Accepted</p><p><strong>Date:</strong> 2026-08-09 <strong>Tags:</strong> infrastructure, terraform, cloudflare, deployment</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><ul><li>Terraform and Wrangler both configured the same Workers. Terraform declared <code>subdomain.enabled</code> while every <code>wrangler.jsonc</code> set <code>workers_dev: false</code>, so each tool undid the other. Terraform also re-derived worker names with its own <code>-${environment}</code> suffix rule that had to stay in lockstep with Wrangler&#39;s.</li><li>The split had no upside: Terraform created Workers without code, and <code>wrangler deploy</code> creates a missing Worker anyway.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Terraform provisions only what the Workers consume: two Hyperdrive configurations per environment, plus an opt-in R2 uploads bucket. Wrangler owns worker names, code, routes, custom domains, bindings, vars and secrets. No field is managed by both.</li><li>The public hostname moves to a Wrangler <a href="https://developers.cloudflare.com/workers/configuration/routing/custom-domains/" target="_blank" rel="noreferrer">Custom Domain</a>, since the <code>web</code> worker is the origin. Wrangler creates the DNS record and certificate, so Terraform owns no DNS and needs no zone permissions.</li><li>The only values crossing the boundary are stable, non-secret resource identifiers: the two Hyperdrive IDs, plus the R2 bucket name when the optional uploads bucket is enabled.</li></ul><h2 id="alternatives-brief" tabindex="-1">Alternatives (brief) <a class="header-anchor" href="#alternatives-brief" aria-label="Permalink to “Alternatives (brief)”">​</a></h2><ul><li><strong>Terraform owns Worker versions and deployments too</strong> – couples every application deploy to an infrastructure apply, and Cloudflare requires replicating the whole Wrangler config into the uploading tool.</li><li><strong>Drop Terraform, use <code>wrangler hyperdrive create</code></strong> – simpler onboarding, but loses declarative reproducibility and drift detection for the one durable, credential-bearing resource.</li><li><strong>Keep the placeholder <code>AAAA 100::</code> DNS record and plain routes</strong> – still workable, and still necessary if you split one hostname across several Workers by path. It reintroduces the ordering dependency where Terraform must create DNS before Wrangler can attach a route.</li></ul><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to “Impact”">​</a></h2><ul><li>Positive: application deploys never run Terraform; Terraform&#39;s API token needs only Hyperdrive access, plus R2 when the uploads bucket is enabled – never workers, routes or DNS; there is one answer to &quot;which tool owns this field&quot;.</li><li>Negative/Risks: Hyperdrive IDs are copied into <code>wrangler.jsonc</code> by hand once per environment. A Custom Domain claims the whole hostname, so serving a second Worker from a path on it requires switching back to routes plus a DNS record.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to “Links”">​</a></h2><ul><li>Code/Docs: <code>infra/README.md</code>, <code>infra/modules/cloudflare/</code>, <a href="/deployment/cloudflare">Deployment</a></li><li>Related ADRs: <a href="/adr/001-auth-hint-cookie">ADR-001</a></li></ul>',14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};